<?php
class Profile {
 public function getBuyer():array{$s=db()->prepare('SELECT * FROM users WHERE id=?');$s->execute([currentBuyerId()]);$u=$s->fetch();return $u?:[];}
 public function save(array $d,?array $file=null):array{$u=$this->getBuyer();$fields=['name','email','phone','city','district','address'];$vals=[];foreach($fields as $f)$vals[$f]=trim((string)($d[$f]??$u[$f]??''));$image=$u['profile_image']??null;if($file&&($file['error']??4)===UPLOAD_ERR_OK){$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(isset($allowed[$file['type']])){$dir=__DIR__.'/../../uploads';if(!is_dir($dir))mkdir($dir,0775,true);$fn='buyer_'.time().'.'.$allowed[$file['type']];move_uploaded_file($file['tmp_name'],$dir.'/'.$fn);$image=url('uploads/'.$fn);}}$s=db()->prepare('UPDATE users SET name=?,email=?,phone=?,city=?,district=?,address=?,profile_image=? WHERE id=?');$s->execute([$vals['name'],$vals['email'],$vals['phone'],$vals['city'],$vals['district'],$vals['address'],$image,currentBuyerId()]);$_SESSION['buyer_name']=$vals['name'];$_SESSION['buyer_email']=$vals['email'];return $this->getBuyer();}
 public function getStats():array{$s=db()->prepare("SELECT status,COUNT(*) c FROM orders WHERE user_id=? GROUP BY status");$s->execute([currentBuyerId()]);$r=['total'=>0,'delivered'=>0,'pending'=>0,'cancelled'=>0];foreach($s as $x){$r['total']+=(int)$x['c'];if($x['status']==='Delivered')$r['delivered']+=(int)$x['c'];elseif($x['status']==='Cancelled')$r['cancelled']+=(int)$x['c'];else$r['pending']+=(int)$x['c'];}return $r;}
}
